class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        seen = {}  # 哈希表：数值 -> 下标
        for i, x in enumerate(nums):
            if target - x in seen:  # 查差值是否已见过
                return [seen[target - x], i]
            seen[x] = i  # 存入当前数

class Solution:
    def reverseList(self, head: ListNode) -> ListNode:
        prev = None
        cur = head
        while cur:
            next_node = cur.next  # 保存下一个
            cur.next = prev  # 反转指针
            prev = cur  # prev后移
            cur = next_node  # cur后移
        return prev  # prev是新头

class Solution:
    def maxArea(self, height: List[int]) -> int:
        left = 0
        right = len(height) - 1
        max_area = 0
        while left < right:
            area = min(height[left], height[right]) * (right - left)  # 计算面积
            max_area = max(max_area, area)  # 更新最大
            if height[left] < height[right]:  # 移动短板
                left += 1
            else:
                right -= 1
        return max_area

class Solution:
    def maxDepth(self, root: TreeNode) -> int:
        if not root:  # 递归终止
            return 0
        return max(self.maxDepth(root.left), self.maxDepth(root.right)) + 1

class Solution:
    def isSymmetric(self, root: TreeNode) -> bool:
        def check(p, q):
            if not p and not q:  # 两节点都空
                return True
            if not p or not q:  # 一方空
                return False
            return p.val == q.val and check(p.left, q.right) and check(p.right, q.left)
        return check(root.left, root.right) if root else True

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        while root:
            if p.val < root.val and q.val < root.val:  # 都在左
                root = root.left
            elif p.val > root.val and q.val > root.val:  # 都在右
                root = root.right
            else:  # 分叉点
                return root
        return root

class Solution:
    def maxPathSum(self, root: TreeNode) -> int:
        self.max_sum = float('-inf')

        def dfs(node):
            if not node:
                return 0
            left = max(0, dfs(node.left))  # 左贡献，负则取0
            right = max(0, dfs(node.right))  # 右贡献，负则取0
            self.max_sum = max(self.max_sum, left + right + node.val)  # 更新全局最大
            return max(left, right) + node.val  # 返回该节点能提供的最大贡献

        dfs(root)
        return self.max_sum

class Solution:
    def isValidBST(self, root: TreeNode) -> bool:
        def dfs(node, lower, upper):
            if not node:
                return True
            if node.val <= lower or node.val >= upper:  # 不在界内
                return False
            return dfs(node.left, lower, node.val) and dfs(node.right, node.val, upper)
        return dfs(root, float('-inf'), float('inf'))

class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        result = []
        path = []

        def backtrack(start):
            result.append(path[:])  # 每个节点都加入结果
            for i in range(start, len(nums)):
                path.append(nums[i])  # 选
                backtrack(i + 1)  # 不回头
                path.pop()  # 撤销

        backtrack(0)
        return result

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid:
            return 0
        count = 0
        m, n = len(grid), len(grid[0])

        def dfs(i, j):
            if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == '0':  # 边界或水
                return
            grid[i][j] = '0'  # 沉没
            dfs(i + 1, j)
            dfs(i - 1, j)
            dfs(i, j + 1)
            dfs(i, j - 1)

        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1':  # 发现岛屿
                    count += 1
                    dfs(i, j)  # 沉没
        return count

class Solution:
    def climbStairs(self, n: int) -> int:
        if n <= 2:
            return n
        dp = [0] * (n + 1)
        dp[1] = 1
        dp[2] = 2
        for i in range(3, n + 1):
            dp[i] = dp[i - 1] + dp[i - 2]
        return dp[n]

import bisect

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        dp = []  # dp[i]是长度为i+1的递增子序列的最小末尾
        for num in nums:
            pos = bisect.bisect_left(dp, num)  # 二分查找位置
            if pos == len(dp):
                dp.append(num)
            else:
                dp[pos] = num
        return len(dp)

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        dp = [float('inf')] * (amount + 1)  # dp[i]凑成i所需最少硬币
        dp[0] = 0  # 基础
        for coin in coins:
            for i in range(coin, amount + 1):  # 正序，完全背包
                dp[i] = min(dp[i], dp[i - coin] + 1)
        return dp[amount] if dp[amount] != float('inf') else -1

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        m, n = len(text1), len(text2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if text1[i - 1] == text2[j - 1]:  # 相等
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:  # 不等
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
        return dp[m][n]

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            dp[i][0] = i  # 删除i个字符
        for j in range(n + 1):
            dp[0][j] = j  # 插入j个字符
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]  # 相等不操作
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1  # 删插替
        return dp[m][n]

class Solution:
    def rob(self, nums: List[int]) -> int:
        if not nums:
            return 0
        if len(nums) == 1:
            return nums[0]
        prev = nums[0]  # dp[i-2]
        curr = max(nums[0], nums[1])  # dp[i-1]
        for i in range(2, len(nums)):
            prev, curr = curr, max(curr, prev + nums[i])  # 选或不选第i间
        return curr

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        min_price = float('inf')  # 最低价
        max_profit = 0  # 最大利润
        for price in prices:
            min_price = min(min_price, price)  # 更新最低价
            max_profit = max(max_profit, price - min_price)  # 更新利润
        return max_profit

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        profit = 0
        for i in range(1, len(prices)):
            if prices[i] > prices[i - 1]:  # 上升段
                profit += prices[i] - prices[i - 1]
        return profit

class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        max_sum = nums[0]  # 全局最大
        cur_sum = nums[0]  # 以i结尾的最大子序和
        for i in range(1, len(nums)):
            cur_sum = max(nums[i], cur_sum + nums[i])  # 负则重新开始
            max_sum = max(max_sum, cur_sum)  # 更新全局最大
        return max_sum

