class Solution:
    def maxEnvelopes(self, envelopes: List[List[int]]) -> int:
        envelopes.sort(key=lambda x: (x[0], -x[1]))  # 宽升序，高降序
        dp = []  # 存递增序列的最小末尾
        for _, h in envelopes:
            pos = bisect.bisect_left(dp, h)  # 对高求LIS
            if pos == len(dp):
                dp.append(h)
            else:
                dp[pos] = h
        return len(dp)

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        left = 0
        right = len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                return mid
            if nums[left] <= nums[mid]:  # 左半边有序
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:  # 右半边有序
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1
        return -1

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def find_bound(nums, target, left):
            lo, hi = 0, len(nums)
            while lo < hi:
                mid = (lo + hi) // 2
                if nums[mid] > target or (left and nums[mid] == target):
                    hi = mid
                else:
                    lo = mid + 1
            return lo

        left = find_bound(nums, target, True)
        if left == len(nums) or nums[left] != target:
            return [-1, -1]
        right = find_bound(nums, target, False)
        return [left, right - 1]

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        if len(nums1) > len(nums2):  # 确保nums1是短的
            nums1, nums2 = nums2, nums1
        m, n = len(nums1), len(nums2)
        left = 0
        right = m
        while left <= right:
            i = (left + right) // 2  # nums1的分割位置
            j = (m + n + 1) // 2 - i  # nums2的分割位置
            nums1_left_max = float('-inf') if i == 0 else nums1[i - 1]
            nums1_right_min = float('inf') if i == m else nums1[i]
            nums2_left_max = float('-inf') if j == 0 else nums2[j - 1]
            nums2_right_min = float('inf') if j == n else nums2[j]
            if nums1_left_max <= nums2_right_min and nums2_left_max <= nums1_right_min:
                if (m + n) % 2 == 0:
                    return (max(nums1_left_max, nums2_left_max) + min(nums1_right_min, nums2_right_min)) / 2
                else:
                    return max(nums1_left_max, nums2_left_max)
            elif nums1_left_max > nums2_right_min:
                right = i - 1
            else:
                left = i + 1
        return 0.0

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        prefix = {0: 1}  # 前缀和->次数
        cur = 0
        count = 0
        for num in nums:
            cur += num  # 累加前缀和
            count += prefix.get(cur - k, 0)  # 找差值
            prefix[cur] = prefix.get(cur, 0) + 1  # 存入当前和
        return count

class Solution:
    def findMaxLength(self, nums: List[int]) -> int:
        prefix = {0: -1}  # 前缀和->首次位置
        cur = 0
        max_len = 0
        for i, num in enumerate(nums):
            cur += 1 if num == 1 else -1  # 0变-1
            if cur in prefix:
                max_len = max(max_len, i - prefix[cur])
            else:
                prefix[cur] = i  # 首次出现
        return max_len

class Solution:
    def canJump(self, nums: List[int]) -> bool:
        max_reach = 0  # 最远可达位置
        for i, jump in enumerate(nums):
            if i > max_reach:  # 当前位置不可达
                return False
            max_reach = max(max_reach, i + jump)  # 更新最远
            if max_reach >= len(nums) - 1:  # 能到末尾
                return True
        return True

class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        if not intervals:
            return []
        intervals.sort(key=lambda x: x[0])  # 按起点排序
        result = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= result[-1][1]:  # 重叠
                result[-1][1] = max(result[-1][1], end)
            else:
                result.append([start, end])
        return result

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        result = 0
        for num in nums:
            result ^= num  # 异或
        return result

