from collections import deque

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        graph = [[] for _ in range(numCourses)]  # 邻接表
        indegree = [0] * numCourses  # 入度
        for u, v in prerequisites:
            graph[v].append(u)  # v->u
            indegree[u] += 1
        queue = deque([i for i in range(numCourses) if indegree[i] == 0])  # 入度0入队
        visited = 0
        while queue:
            course = queue.popleft()
            visited += 1
            for next_course in graph[course]:
                indegree[next_course] -= 1
                if indegree[next_course] == 0:
                    queue.append(next_course)
        return visited == numCourses

class Trie:
    def __init__(self):
        self.children = {}  # 子节点
        self.is_end = False  # 是否结束

    def insert(self, word: str) -> None:
        node = self
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Trie()
            node = node.children[ch]
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._search_prefix(word)
        return node is not None and node.is_end

    def startsWith(self, prefix: str) -> bool:
        return self._search_prefix(prefix) is not None

    def _search_prefix(self, prefix: str):
        node = self
        for ch in prefix:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        count = 0
        candidate = None
        for num in nums:
            if count == 0:  # 换候选人
                candidate = num
            count += 1 if num == candidate else -1  # 票数抵消
        return candidate

class Solution:
    def isHappy(self, n: int) -> bool:
        def next_num(x):
            return sum(int(d) ** 2 for d in str(x))

        slow = n
        fast = next_num(n)
        while fast != 1 and slow != fast:
            slow = next_num(slow)  # 慢走一步
            fast = next_num(next_num(fast))  # 快走两步
        return fast == 1
